window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7a3c6ac9a559d86e"]={"versions": [{"id": "FIG-7a3c6ac9a559d86e", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des AUTOSAR-ECU-Konfigurationsmodells (BSW Parameter Definition) für das Modul <code>DoIP</code> (Diagnostic over IP). Das Metamodell definiert die hierarchische Struktur und Parametrierung des Konfigurationscontainers <code>DoIPChannel</code> sowie dessen Assoziationen zu PDU-Router-Schnittstellen, logischen DoIP-Testern und Zieladressen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>DoIPChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65536). Er besitzt folgende Referenzen und Untercontainer:</p>\n<ul class=\"fig-list\"><li><code>DoIPChannelSARef</code> (<code>EcucReferenceDef</code>, 1..1) referenziert als Destination den Container <code>DoIPTester</code> (<code>EcucParamConfContainerDef</code>, 1..255).\n</li><li><code>DoIPChannelTARef</code> (<code>EcucReferenceDef</code>, 1..1) referenziert als Destination den Container <code>DoIPTargetAddress</code> (<code>EcucParamConfContainerDef</code>, 1..65535).\n</li><li>Untercontainer <code>DoIPPduRRxPdu</code> (<code>EcucParamConfContainerDef</code>, 0..1):\n<ul class=\"fig-list\"><li>Parameter <code>DoIPPduRRxPduId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>DoIPPduRRxPduRef</code> (<code>EcucReferenceDef</code>) mit Destination auf den externen Container <code>Pdu</code> (<code>EcucParamConfContainerDef</code>, 0..*).\n</li></ul>\n</li><li>Untercontainer <code>DoIPPduRTxPdu</code> (<code>EcucParamConfContainerDef</code>, 0..1):\n<ul class=\"fig-list\"><li>Parameter <code>DoIPPduRTxPduId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>DoIPPduRTxPduRef</code> (<code>EcucReferenceDef</code>) mit Destination auf den externen Container <code>Pdu</code>.\n</li><li>Parameter <code>DoIPPduType</code> (<code>EcucEnumerationParamDef</code>, 0..1, <code>defaultValue = DOIP_TPPDU</code>) mit den Enumeration-Literalen <code>DOIP_IFPDU</code> und <code>DOIP_TPPDU</code> (<code>EcucEnumerationLiteralDef</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Laufzeitsequenzen. Die Parameter und Referenzen legen zur Konfigurations- bzw. Generierungszeit fest, wie ein logischer DoIP-Diagnosekanal zwischen Tester-Quelladresse (<code>DoIPChannelSARef</code>) und Zieladresse (<code>DoIPChannelTARef</code>) über Rx- und Tx-PDUs an das PDU-Router-Modul (<code>PduR</code>) angebunden und typisiert (Transport-Protocol- vs. Interface-PDU) wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die DoIP-Modulkonfiguration im BSW-Stack. Für jeden <code>DoIPChannel</code> muss genau eine Quelladress- und eine Zieladress-Referenz konfiguriert werden. Die PDU-Zuordnungen für Rx und Tx sind optional (0..1). Sofern konfiguriert, müssen die PDU-IDs im Bereich von 0 bis 65535 liegen und als symbolische Namen generiert werden. Fehlt der Parameter <code>DoIPPduType</code>, greift der Standardwert <code>DOIP_TPPDU</code>.</p>"}, {"id": "FIG-55b8d975772b2054", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des AUTOSAR-ECU-Konfigurationsmodells (BSW Parameter Definition) für das Modul <code>DoIP</code> (Diagnostic over IP). Das Metamodell definiert die hierarchische Struktur und Parametrierung des Konfigurationscontainers <code>DoIPChannel</code> sowie dessen Assoziationen zu PDU-Router-Schnittstellen, logischen DoIP-Testern und Zieladressen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>DoIPChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65536). Er besitzt folgende Referenzen und Untercontainer:</p>\n<ul class=\"fig-list\"><li><code>DoIPChannelSARef</code> (<code>EcucReferenceDef</code>, 1..1) referenziert als Destination den Container <code>DoIPTester</code> (<code>EcucParamConfContainerDef</code>, 1..255).\n</li><li><code>DoIPChannelTARef</code> (<code>EcucReferenceDef</code>, 1..1) referenziert als Destination den Container <code>DoIPTargetAddress</code> (<code>EcucParamConfContainerDef</code>, 1..65535).\n</li><li>Untercontainer <code>DoIPPduRRxPdu</code> (<code>EcucParamConfContainerDef</code>, 0..1):\n<ul class=\"fig-list\"><li>Parameter <code>DoIPPduRRxPduId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>DoIPPduRRxPduRef</code> (<code>EcucReferenceDef</code>) mit Destination auf den externen Container <code>Pdu</code> (<code>EcucParamConfContainerDef</code>, 0..*).\n</li></ul>\n</li><li>Untercontainer <code>DoIPPduRTxPdu</code> (<code>EcucParamConfContainerDef</code>, 0..1):\n<ul class=\"fig-list\"><li>Parameter <code>DoIPPduRTxPduId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>DoIPPduRTxPduRef</code> (<code>EcucReferenceDef</code>) mit Destination auf den externen Container <code>Pdu</code>.\n</li><li>Parameter <code>DoIPPduType</code> (<code>EcucEnumerationParamDef</code>, 0..1, <code>defaultValue = DOIP_TPPDU</code>) mit den Enumeration-Literalen <code>DOIP_IFPDU</code> und <code>DOIP_TPPDU</code> (<code>EcucEnumerationLiteralDef</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Laufzeitsequenzen. Die Parameter und Referenzen legen zur Konfigurations- bzw. Generierungszeit fest, wie ein logischer DoIP-Diagnosekanal zwischen Tester-Quelladresse (<code>DoIPChannelSARef</code>) und Zieladresse (<code>DoIPChannelTARef</code>) über Rx- und Tx-PDUs an das PDU-Router-Modul (<code>PduR</code>) angebunden und typisiert (Transport-Protocol- vs. Interface-PDU) wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die DoIP-Modulkonfiguration im BSW-Stack. Für jeden <code>DoIPChannel</code> muss genau eine Quelladress- und eine Zieladress-Referenz konfiguriert werden. Die PDU-Zuordnungen für Rx und Tx sind optional (0..1). Sofern konfiguriert, müssen die PDU-IDs im Bereich von 0 bis 65535 liegen und als symbolische Namen generiert werden. Fehlt der Parameter <code>DoIPPduType</code>, greift der Standardwert <code>DOIP_TPPDU</code>.</p>"}, {"id": "FIG-cc247cabac42ba72", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des AUTOSAR-ECU-Konfigurationsmodells (BSW Parameter Definition) für das Modul <code>DoIP</code> (Diagnostic over IP). Das Metamodell definiert die hierarchische Struktur und Parametrierung des Konfigurationscontainers <code>DoIPChannel</code> sowie dessen Assoziationen zu PDU-Router-Schnittstellen, logischen DoIP-Testern und Zieladressen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>DoIPChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65536). Er besitzt folgende Referenzen und Untercontainer:</p>\n<ul class=\"fig-list\"><li><code>DoIPChannelSARef</code> (<code>EcucReferenceDef</code>, 1..1) referenziert als Destination den Container <code>DoIPTester</code> (<code>EcucParamConfContainerDef</code>, 1..255).\n</li><li><code>DoIPChannelTARef</code> (<code>EcucReferenceDef</code>, 1..1) referenziert als Destination den Container <code>DoIPTargetAddress</code> (<code>EcucParamConfContainerDef</code>, 1..65535).\n</li><li>Untercontainer <code>DoIPPduRRxPdu</code> (<code>EcucParamConfContainerDef</code>, 0..1):\n<ul class=\"fig-list\"><li>Parameter <code>DoIPPduRRxPduId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>withAuto = true</code>, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>DoIPPduRRxPduRef</code> (<code>EcucReferenceDef</code>) mit Destination auf den externen Container <code>Pdu</code> (<code>EcucParamConfContainerDef</code>, 0..*).\n</li></ul>\n</li><li>Untercontainer <code>DoIPPduRTxPdu</code> (<code>EcucParamConfContainerDef</code>, 0..1):\n<ul class=\"fig-list\"><li>Parameter <code>DoIPPduRTxPduId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>withAuto = true</code>, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>DoIPPduRTxPduRef</code> (<code>EcucReferenceDef</code>) mit Destination auf den externen Container <code>Pdu</code>.\n</li><li>Parameter <code>DoIPPduType</code> (<code>EcucEnumerationParamDef</code>, 0..1, <code>defaultValue = DOIP_TPPDU</code>) mit den Enumeration-Literalen <code>DOIP_IFPDU</code> und <code>DOIP_TPPDU</code> (<code>EcucEnumerationLiteralDef</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Laufzeitsequenzen. Die Parameter und Referenzen legen zur Konfigurations- bzw. Generierungszeit fest, wie ein logischer DoIP-Diagnosekanal zwischen Tester-Quelladresse (<code>DoIPChannelSARef</code>) und Zieladresse (<code>DoIPChannelTARef</code>) über Rx- und Tx-PDUs an das PDU-Router-Modul (<code>PduR</code>) angebunden und typisiert (Transport-Protocol- vs. Interface-PDU) wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die DoIP-Modulkonfiguration im BSW-Stack. Für jeden <code>DoIPChannel</code> muss genau eine Quelladress- und eine Zieladress-Referenz konfiguriert werden. Die PDU-Zuordnungen für Rx und Tx sind optional (0..1). Für die Parameter <code>DoIPPduRRxPduId</code> und <code>DoIPPduRTxPduId</code> ist die automatische Wertvergabe durch Konfigurationswerkzeuge zulässig (<code>withAuto = true</code>), der Wertebereich liegt zwischen 0 und 65535 und sie werden als symbolische Namen generiert. Fehlt der Parameter <code>DoIPPduType</code>, greift der Standardwert <code>DOIP_TPPDU</code>.</p>"}, {"id": "FIG-5956ce6ff0ee1e28", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des AUTOSAR-ECU-Konfigurationsmodells (BSW Parameter Definition) für das Modul <code>DoIP</code> (Diagnostic over IP). Das Metamodell definiert die hierarchische Struktur und Parametrierung des Konfigurationscontainers <code>DoIPChannel</code> sowie dessen Assoziationen zu PDU-Router-Schnittstellen, logischen DoIP-Testern und Zieladressen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>DoIPChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65536). Er besitzt folgende Referenzen und Untercontainer:</p>\n<ul class=\"fig-list\"><li><code>DoIPChannelSARef</code> (<code>EcucReferenceDef</code>, 1..1) referenziert als Destination den Container <code>DoIPTester</code> (<code>EcucParamConfContainerDef</code>, 1..255).\n</li><li><code>DoIPChannelTARef</code> (<code>EcucReferenceDef</code>, 1..1) referenziert als Destination den Container <code>DoIPTargetAddress</code> (<code>EcucParamConfContainerDef</code>, 1..65535).\n</li><li>Untercontainer <code>DoIPPduRRxPdu</code> (<code>EcucParamConfContainerDef</code>, 0..1):\n<ul class=\"fig-list\"><li>Parameter <code>DoIPPduRRxPduId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>withAuto = true</code>, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>DoIPPduRRxPduRef</code> (<code>EcucReferenceDef</code>) mit Destination auf den externen Container <code>Pdu</code> (<code>EcucParamConfContainerDef</code>, 0..*).\n</li></ul>\n</li><li>Untercontainer <code>DoIPPduRTxPdu</code> (<code>EcucParamConfContainerDef</code>, 0..1):\n<ul class=\"fig-list\"><li>Parameter <code>DoIPPduRTxPduId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>withAuto = true</code>, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>DoIPPduRTxPduRef</code> (<code>EcucReferenceDef</code>) mit Destination auf den externen Container <code>Pdu</code>.\n</li><li>Parameter <code>DoIPPduType</code> (<code>EcucEnumerationParamDef</code>, 0..1, <code>defaultValue = DOIP_TPPDU</code>) mit den Enumeration-Literalen <code>DOIP_IFPDU</code> und <code>DOIP_TPPDU</code> (<code>EcucEnumerationLiteralDef</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Laufzeitsequenzen. Die Parameter und Referenzen legen zur Konfigurations- bzw. Generierungszeit fest, wie ein logischer DoIP-Diagnosekanal zwischen Tester-Quelladresse (<code>DoIPChannelSARef</code>) und Zieladresse (<code>DoIPChannelTARef</code>) über Rx- und Tx-PDUs an das PDU-Router-Modul (<code>PduR</code>) angebunden und typisiert (Transport-Protocol- vs. Interface-PDU) wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die DoIP-Modulkonfiguration im BSW-Stack. Für jeden <code>DoIPChannel</code> muss genau eine Quelladress- und eine Zieladress-Referenz konfiguriert werden. Die PDU-Zuordnungen für Rx und Tx sind optional (0..1). Für die Parameter <code>DoIPPduRRxPduId</code> und <code>DoIPPduRTxPduId</code> ist die automatische Wertvergabe durch Konfigurationswerkzeuge zulässig (<code>withAuto = true</code>), der Wertebereich liegt zwischen 0 und 65535 und sie werden als symbolische Namen generiert. Fehlt der Parameter <code>DoIPPduType</code>, greift der Standardwert <code>DOIP_TPPDU</code>.</p>"}, {"id": "FIG-02afb4b9a0444b56", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des AUTOSAR-ECU-Konfigurationsmodells (BSW Parameter Definition) für das Modul <code>DoIP</code> (Diagnostic over IP). Das Metamodell definiert die hierarchische Struktur und Parametrierung des Konfigurationscontainers <code>DoIPChannel</code> sowie dessen Assoziationen zu PDU-Router-Schnittstellen, logischen DoIP-Testern und Zieladressen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>DoIPChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65536). Er besitzt folgende Referenzen und Untercontainer:</p>\n<ul class=\"fig-list\"><li><code>DoIPChannelSARef</code> (<code>EcucReferenceDef</code>, 1..1) referenziert als Destination den Container <code>DoIPTester</code> (<code>EcucParamConfContainerDef</code>, 1..255).\n</li><li><code>DoIPChannelTARef</code> (<code>EcucReferenceDef</code>, 1..1) referenziert als Destination den Container <code>DoIPTargetAddress</code> (<code>EcucParamConfContainerDef</code>, 1..65535).\n</li><li>Untercontainer <code>DoIPPduRRxPdu</code> (<code>EcucParamConfContainerDef</code>, 1..1):\n<ul class=\"fig-list\"><li>Parameter <code>DoIPPduRRxPduId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>withAuto = true</code>, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>DoIPPduRRxPduRef</code> (<code>EcucReferenceDef</code>) mit Destination auf den externen Container <code>Pdu</code> (<code>EcucParamConfContainerDef</code>, 0..*).\n</li></ul>\n</li><li>Untercontainer <code>DoIPPduRTxPdu</code> (<code>EcucParamConfContainerDef</code>, 1..1):\n<ul class=\"fig-list\"><li>Parameter <code>DoIPPduRTxPduId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>withAuto = true</code>, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>DoIPPduRTxPduRef</code> (<code>EcucReferenceDef</code>) mit Destination auf den externen Container <code>Pdu</code>.\n</li><li>Parameter <code>DoIPPduType</code> (<code>EcucEnumerationParamDef</code>, 1..1, <code>defaultValue = DOIP_TPPDU</code>) mit den Enumeration-Literalen <code>DOIP_IFPDU</code> und <code>DOIP_TPPDU</code> (<code>EcucEnumerationLiteralDef</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Laufzeitsequenzen. Die Parameter und Referenzen legen zur Konfigurations- bzw. Generierungszeit fest, wie ein logischer DoIP-Diagnosekanal zwischen Tester-Quelladresse (<code>DoIPChannelSARef</code>) und Zieladresse (<code>DoIPChannelTARef</code>) über Rx- und Tx-PDUs an das PDU-Router-Modul (<code>PduR</code>) angebunden und typisiert (Transport-Protocol- vs. Interface-PDU) wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die DoIP-Modulkonfiguration im BSW-Stack. Für jeden <code>DoIPChannel</code> sind die Referenzen auf Quelladresse (<code>DoIPChannelSARef</code>), Zieladresse (<code>DoIPChannelTARef</code>) sowie die Untercontainer für Rx- und Tx-PDUs (<code>DoIPPduRRxPdu</code> und <code>DoIPPduRTxPdu</code>) zwingend mit Multiplizität 1..1 zu konfigurieren. Der Parameter <code>DoIPPduType</code> ist verpflichtend (1..1) und besitzt den Standardwert <code>DOIP_TPPDU</code>. Für <code>DoIPPduRRxPduId</code> und <code>DoIPPduRTxPduId</code> ist die automatische Wertvergabe durch Konfigurationswerkzeuge aktiviert (<code>withAuto = true</code>), Wertebereich ist 0 bis 65535 mit symbolischer Namensgenerierung.</p>"}], "trans": [{"from": "FIG-7a3c6ac9a559d86e", "to": "FIG-55b8d975772b2054", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-55b8d975772b2054", "to": "FIG-cc247cabac42ba72", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DoIPPduRRxPduId</code>: Eigenschaft <code>withAuto = true</code> ergänzt.\n</li><li><code>DoIPPduRTxPduId</code>: Eigenschaft <code>withAuto = true</code> ergänzt.\n</li></ul>"}, {"from": "FIG-cc247cabac42ba72", "to": "FIG-5956ce6ff0ee1e28", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5956ce6ff0ee1e28", "to": "FIG-02afb4b9a0444b56", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DoIPPduRRxPdu</code>: <code>lowerMultiplicity</code> von <code>0</code> auf <code>1</code> geändert.\n</li><li><code>DoIPPduRTxPdu</code>: <code>lowerMultiplicity</code> von <code>0</code> auf <code>1</code> geändert.\n</li><li><code>DoIPPduType</code>: <code>lowerMultiplicity</code> von <code>0</code> auf <code>1</code> geändert (Zeilenreihenfolge im Kasten neu formatiert: <code>defaultValue = DOIP_TPPDU</code>, <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).\n</li></ul>"}]};
